#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void compute_row_norms_kernel(const float* a, float* norm_out, int rows_per_block, int total_rows, int dim_size) {
    const int row = blockIdx.x * blockDim.x + threadIdx.x;
    if (row < total_rows) {
        float sum = 0.0f;
        for (int j = 0; j < dim_size; ++j) {
            float val = a[row * dim_size + j];
            sum += val * val;
        }
        norm_out[row] = sqrt(sum);
    }
}

__global__ void normalize_kernel(const float* a, const float* norm_out, float* out, int rows_per_block, int total_rows, int dim_size) {
    const int row = blockIdx.x * blockDim.x + threadIdx.x;
    if (row < total_rows) {
        for (int j = 0; j < dim_size; ++j) {
            out[row * dim_size + j] = a[row * dim_size + j] / norm_out[row];
        }
    }
}

torch::Tensor l2norm_cuda(torch::Tensor x) {
    auto size = x.numel();
    int batch_size = x.size(0);
    int dim_size = x.size(1);

    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;

    float* norm_out = new float[size];
    compute_row_norms_kernel<<<num_blocks, block_size>>>(x.data_ptr<float>(), norm_out, num_blocks, batch_size, dim_size);
    normalize_kernel<<<num_blocks, block_size>>>(x.data_ptr<float>(), norm_out, x.data_ptr<float>(), num_blocks, batch_size, dim_size);
    delete[] norm_out;

    auto out = torch::zeros_like(x);
    return out;
}
"""

